import React from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { Shield, User, LogOut, Globe, ShieldAlert, FileSearch, Lock, Server } from 'lucide-react';

export default function Navbar({ user, onLogout }) {
  const navigate = useNavigate();
  const location = useLocation();

  // Handles smooth scrolling to specific tool sections or landing partitions
  const scrollToSection = (sectionId) => {
    if (location.pathname !== '/') {
      navigate('/');
      setTimeout(() => {
        const element = document.getElementById(sectionId);
        if (element) element.scrollIntoView({ behavior: 'smooth' });
      }, 150);
    } else {
      const element = document.getElementById(sectionId);
      if (element) element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <nav style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '14px 32px',
      backgroundColor: 'rgba(10, 13, 18, 0.85)',
      backdropFilter: 'blur(12px)',
      borderBottom: '1px solid var(--border-glow)',
      position: 'sticky',
      top: 0,
      zIndex: 1000
    }}>
      <div 
        onClick={() => scrollToSection('hero-section')} 
        style={{ display: 'flex', alignItems: 'center', gap: '12px', cursor: 'pointer' }}
      >
        <Shield size={26} color="var(--accent-cyan)" />
        <span className="hacker-glow" style={{ fontSize: '18px', fontWeight: 'bold', fontFamily: 'var(--font-mono)', color: 'var(--accent-cyan)' }}>
          NET_SENTINEL // SOC
        </span>
      </div>

      {/* Header Navigation with Direct Tool Names */}
      <div style={{ display: 'flex', gap: '14px', alignItems: 'center', flexWrap: 'wrap' }}>
        
        <button 
          onClick={() => scrollToSection('tool-host')} 
          className="cyber-button" 
          style={{ padding: '6px 10px', fontSize: '11px', background: 'transparent' }}
          title="Jump to Host & IP Intel"
        >
          <Globe size={13} /> HOST INTEL
        </button>

        <button 
          onClick={() => scrollToSection('tool-port')} 
          className="cyber-button" 
          style={{ padding: '6px 10px', fontSize: '11px', background: 'transparent' }}
          title="Jump to Port Scanner"
        >
          <ShieldAlert size={13} /> PORT CVE
        </button>

        <button 
          onClick={() => scrollToSection('tool-subdomain')} 
          className="cyber-button" 
          style={{ padding: '6px 10px', fontSize: '11px', background: 'transparent' }}
          title="Jump to Subdomain Enumeration"
        >
          <FileSearch size={13} /> SUBDOMAINS
        </button>

        <button 
          onClick={() => scrollToSection('tool-dir')} 
          className="cyber-button" 
          style={{ padding: '6px 10px', fontSize: '11px', background: 'transparent' }}
          title="Jump to Directory Bruteforce"
        >
          <Lock size={13} /> DIR EXPOSURE
        </button>

        <button 
          onClick={() => scrollToSection('tool-ssl')} 
          className="cyber-button" 
          style={{ padding: '6px 10px', fontSize: '11px', background: 'transparent' }}
          title="Jump to SSL Auditor"
        >
          <Server size={13} /> SSL AUDIT
        </button>

        {user ? (
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginLeft: '10px' }}>
            <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--accent-green)', fontSize: '12px' }}>
              [{user.name}]
            </span>
            <button className="cyber-button" onClick={() => { onLogout(); navigate('/'); }} style={{ padding: '6px 10px' }}>
              <LogOut size={14} />
            </button>
          </div>
        ) : (
          <Link to="/login" className="cyber-button" style={{ padding: '8px 14px', fontSize: '11px', backgroundColor: 'rgba(0, 243, 255, 0.1)' }}>
            <User size={14} /> LOGIN
          </Link>
        )}
      </div>
    </nav>
  );
}
